72:   function openModal(title,kicker,html,actions=[]){moveEnabled=false;const root=$('modalRoot');root.innerHTML=`<div class="modal-backdrop"><section class="modal"><header class="modal-top"><div><div class="eyebrow">${kicker}</div><h2>${title}</h2></div><button class="close-modal" aria-label="Close">×</button></header><div class="modal-body">${html}${actions.length?`<div class="modal-actions">${actions.map((a,i)=>`<button class="action-button ${a.kind||''}" data-action="${i}">${a.label}</button>`).join('')}</div>`:''}</div></section></div>`;root.querySelector('.close-modal').onclick=closeModal;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[+b.dataset.action].run());}
